  background: rgba(94, 234, 212, .05); margin-bottom: 22px;
}
.t-badge i { width: 6px; height: 6px; border-radius: 50%; background: var(--teal); box-shadow: 0 0 10px var(--teal); animation: pulse 2s infinite; }
@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: .35; } }
.t-logo {
  font-family: var(--mono); font-size: clamp(44px, 9vw, 76px); font-weight: 800;
  letter-spacing: -.04em; line-height: .95; margin: 0 0 18px; display: flex; justify-content: center; gap: .18em;
}
.t-logo span { color: #f3f8ff; text-shadow: 0 0 40px rgba(255, 255, 255, .18); }
.t-logo em {
  font-style: normal;
  background: linear-gradient(135deg, #5eead4 10%, #38bdf8 55%, #a78bfa 95%);
