.dice { width: 52px; height: 52px; border-radius: 12px; border: 1px solid #2c3b4f; background: #111a25; color: var(--muted); display: grid; place-items: center; cursor: pointer; transition: .18s; }
.dice svg { width: 21px; height: 21px; }
