.t-start { width: 100%; }
.t-continue { width: 100%; margin-top: 9px; }
.t-hint { text-align: center; color: var(--faint); font-size: 11px; margin-top: 13px; }
.t-features { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px 20px; margin-top: 26px; color: #7c8ba1; font-size: 11.5px; }
