}
.t-float span, .t-float b { font-family: var(--mono); font-size: 22px; font-weight: 700; color: var(--teal); }
.t-float small { font-family: var(--mono); font-size: 8px; letter-spacing: .16em; color: var(--faint); }
.t-float.f1 { left: 7%; top: 26%; transform: rotate(-7deg); }
.t-float.f2 { right: 6%; top: 22%; transform: rotate(6deg); animation-delay: -2.4s; }
