.tag.good { color: var(--teal); border-color: rgba(94, 234, 212, .3); background: rgba(94, 234, 212, .07); }
.tag.bad { color: var(--red); border-color: rgba(251, 113, 133, .3); background: rgba(251, 113, 133, .07); }
.tag.warn { color: var(--amber); border-color: rgba(251, 191, 36, .3); background: rgba(251, 191, 36, .07); }
.tag.you { color: var(--violet); border-color: rgba(167, 139, 250, .3); background: rgba(167, 139, 250, .08); }

.bar { height: 7px; border-radius: 99px; background: #0a0f16; overflow: hidden; border: 1px solid rgba(255, 255, 255, .035); }
.bar > i { display: block; height: 100%; border-radius: 99px; background: linear-gradient(90deg, var(--c1, #5eead4), var(--c2, #38bdf8)); transition: width .45s cubic-bezier(.2, .8, .2, 1); box-shadow: 0 0 12px -2px var(--c1, #5eead4); }
.bar.thin { height: 5px; }
.bar.tall { height: 10px; }

.stat-box { padding: 11px 13px; border-radius: 11px; background: rgba(255, 255, 255, .025); border: 1px solid var(--line); }
.stat-box small { display: block; color: var(--faint); font-size: 9.5px; letter-spacing: .08em; text-transform: uppercase; margin-bottom: 4px; }
.stat-box b { font-family: var(--mono); font-size: 17px; font-weight: 650; }
.stat-box b span { font-size: 10px; color: var(--faint); font-weight: 500; }
.stat-row { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; margin-top: 14px; }

.empty-state { text-align: center; padding: 56px 24px; display: flex; flex-direction: column; align-items: center; gap: 8px; }
.empty-state.small { padding: 30px 18px; }
.empty-art { width: 76px; height: 76px; border-radius: 20px; display: grid; place-items: center; color: var(--teal); background: radial-gradient(circle at 30% 20%, rgba(94, 234, 212, .18), rgba(94, 234, 212, .02)); border: 1px solid rgba(94, 234, 212, .18); margin-bottom: 6px; }
.empty-state .btn { margin-top: 12px; }

.live-dot { font-family: var(--mono); font-size: 8.5px; letter-spacing: .16em; color: var(--teal); display: inline-flex; align-items: center; gap: 6px; }
.live-dot::before { content: ""; width: 5px; height: 5px; border-radius: 50%; background: var(--teal); box-shadow: 0 0 8px var(--teal); animation: pulse 1.8s infinite; }

input.newString:
.live-dot::before { content: ""; width: 5px; height: 5px; border-radius: 50%; background: var(--teal); box-shadow: 0 0 8px var(--teal); animation: pulse 1.8s infinite; }

/* ---------------- studio dashboard ---------------- */
.studio-grid { display: grid; grid-template-columns: minmax(0, 1.6fr) minmax(310px, 1fr); gap: 16px; align-items: stretch; }
.office-panel { grid-column: 1; padding: 0; overflow: hidden; display: flex; flex-direction: column; min-height: 320px; }
.office-overlay { position: absolute; z-index: 2; display: flex; gap: 6px; }
.office-overlay.top { top: 12px; left: 12px; right: 12px; justify-content: space-between; }
.office-overlay .chip { background: rgba(8, 12, 18, .68); backdrop-filter: blur(8px); border-color: rgba(255, 255, 255, .09); color: #c3d0e0; }
.office-svg { display: block; width: 100%; height: auto; margin-top: auto; }
.office-foot { display: flex; align-items: center; gap: 6px; padding: 10px 13px; border-top: 1px solid var(--line); background: rgba(8, 12, 18, .45); overflow-x: auto; scrollbar-width: none; }
.office-foot::-webkit-scrollbar { display: none; }
.mini-dev { display: flex; align-items: center; gap: 6px; padding: 4px 8px 4px 4px; border-radius: 8px; background: rgba(255, 255, 255, .025); border: 1px solid rgba(255, 255, 255, .04); flex: none; }
.mini-av { width: 23px; height: 23px; border-radius: 6px; display: grid; place-items: center; font-family: var(--mono); font-size: 8.5px; font-weight: 700; color: #081018; background: linear-gradient(135deg, var(--c, #5eead4), color-mix(in srgb, var(--c, #5eead4) 55%, #0b1017)); }
.mini-name { font-size: 10.5px; color: var(--muted); font-weight: 600; }
.mini-morale { width: 30px; height: 3px; border-radius: 9px; background: #0a0f15; overflow: hidden; }
.mini-morale i { display: block; height: 100%; background: var(--c); }
.mini-dev.empty { opacity: .55; border-style: dashed; }
.mini-dev.empty .mini-av { background: transparent; border: 1px dashed var(--line2); color: var(--faint); }
.mini-dev.more { color: var(--faint); font-size: 10px; padding: 6px 9px; }

.pulse-panel { grid-column: 2; display: flex; flex-direction: column; }
.fin-list { display: flex; flex-direction: column; gap: 7px; }
.fin-row { display: flex; align-items: center; justify-content: space-between; font-size: 12.5px; color: var(--muted); }
.fin-row b { font-family: var(--mono); font-size: 12.5px; color: var(--text); font-weight: 600; }
.fin-row.total { padding-top: 8px; border-top: 1px dashed var(--line); font-weight: 600; color: var(--text); }
.fin-row.total b { font-size: 15px; }
.metric-line { margin-bottom: 11px; }
.metric-top { display: flex; align-items: center; justify-content: space-between; gap: 10px; font-size: 11.5px; color: var(--muted); margin-bottom: 6px; }
.metric-top b { font-family: var(--mono); font-size: 11.5px; color: var(--text); }
.metric-top .ic { color: var(--faint); }
.mini-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-top: 14px; }
.mini-stats > div { padding: 8px 9px; border-radius: 9px; background: rgba(255, 255, 255, .025); border: 1px solid var(--line); }
.mini-stats small { display: block; color: var(--faint); font-size: 9px; text-transform: uppercase; letter-spacing: .08em; margin-bottom: 2px; }
.mini-stats b { font-family: var(--mono); font-size: 12.5px; font-weight: 650; }
.milestone { margin-top: auto; padding-top: 14px; border-top: 1px solid var(--line); }
.milestone small { display: block; color: var(--faint); font-size: 10.5px; margin-top: 6px; }
.milestone.done { display: flex; align-items: center; gap: 8px; color: var(--amber); font-size: 12px; font-weight: 600; }

.project-summary { grid-column: 1; }
.project-summary.empty-project { display: flex; align-items: center; gap: 20px; }
.project-summary.empty-project .empty-art { margin: 0; flex: none; }
.project-summary.empty-project .row-actions { margin-top: 14px; }
.progress-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; font-size: 11.5px; color: var(--muted); margin: 12px 0 7px; }
.progress-head b { font-family: var(--mono); color: var(--text); }
.summary-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; margin: 14px 0 0; }
.summary-grid > div { padding: 9px 11px; border-radius: 9px; background: rgba(255, 255, 255, .025); border: 1px solid var(--line); }
.summary-grid small { display: block; color: var(--faint); font-size: 9.5px; text-transform: uppercase; letter-spacing: .07em; margin-bottom: 3px; }
.summary-grid b { font-family: var(--mono); font-size: 14px; font-weight: 650; }
.row-actions { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 14px; }
.stage-badge {
  display: inline-flex; align-items: center; height: 24px; padding: 0 9px; border-radius: 7px;
  font-family: var(--mono); font-size: 9px; letter-spacing: .12em; text-transform: uppercase; font-weight: 700;
}
.stage-badge.dev { color: var(--teal); background: rgba(94, 234, 212, .09); border: 1px solid rgba(94, 234, 212, .25); }
.stage-badge.polish { color: var(--amber); background: rgba(251, 191, 36, .09); border: 1px solid rgba(251, 191, 36, .25); }
.stage-badge.good { color: var(--teal); background: rgba(94, 234, 212, .09); border: 1px solid rgba(94, 234, 212, .25); }
.stage-badge.warn { color: var(--amber); background: rgba(251, 191, 36, .09); border: 1px solid rgba(251, 191, 36, .25); }
.stage-badge.bad { color: var(--red); background: rgba(251, 113, 133, .09); border: 1px solid rgba(251, 113, 133, .25); }

.news-panel { grid-column: 2; }
.news-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 2px; max-height: 310px; overflow-y: auto; }
.news-item { display: flex; gap: 9px; padding: 8px 4px; border-bottom: 1px solid rgba(255, 255, 255, .04); }
.news-item:last-child { border-bottom: none; }
.news-dot { width: 6px; height: 6px; border-radius: 50%; margin-top: 5px; flex: none; background: var(--faint); }
.news-item.good .news-dot { background: var(--teal); box-shadow: 0 0 7px rgba(94, 234, 212, .7); }
.news-item.bad .news-dot { background: var(--red); box-shadow: 0 0 7px rgba(251, 113, 133, .7); }
.news-item.warn .news-dot { background: var(--amber); }
.news-item.market .news-dot { background: var(--violet); }
.news-item.award .news-dot { background: var(--amber); box-shadow: 0 0 7px rgba(251, 191, 36, .8); }
.news-item p { font-size: 11.5px; line-height: 1.45; color: #b9c6d6; }
.news-item small { display: block; color: var(--faint); font-size: 9.5px; margin-top: 2px; font-family: var(--mono); }

/* ---------------- project detail ---------------- */
.detail-grid { display: grid; grid-template-columns: minmax(0, 1.55fr) minmax(300px, 1fr); gap: 16px; align-items: start; }
.col { display: flex; flex-direction: column; gap: 16px; min-width: 0; }
.focus-list { display: flex; flex-direction: column; gap: 15px; margin-top: 16px; }
.focus-row { display: flex; flex-direction: column; gap: 7px; }
.focus-label { display: flex; align-items: center; gap: 7px; font-size: 12px; font-weight: 650; }
.focus-label .dot { width: 7px; height: 7px; border-radius: 50%; }
.focus-label small { margin-left: auto; font-family: var(--mono); color: var(--muted); font-size: 10.5px; }
input[type="range"].slider {
  -webkit-appearance: none; appearance: none; width: 100%; height: 7px; border-radius: 99px;
  background: linear-gradient(90deg, var(--accent, #5eead4) var(--v, 50%), #1a2431 var(--v, 50%));
  outline: none; cursor: pointer; margin: 0;
}
input[type="range"].slider::-webkit-slider-thumb {
  -webkit-appearance: none; width: 17px; height: 17px; border-radius: 50%;
  background: #f4f9ff; border: 3px solid var(--accent, #5eead4);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--accent, #5eead4) 16%, transparent), 0 2px 6px rgba(0, 0, 0, .5);
  cursor: grab; transition: transform .12s;
}
input[type="range"].slider::-webkit-slider-thumb:active { transform: scale(1.12); cursor: grabbing; }
input[type="range"].slider::-moz-range-thumb { width: 15px; height: 15px; border-radius: 50%; background: #f4f9ff; border: 3px solid var(--accent, #5eead4); }
.focus-share { display: flex; align-items: center; gap: 8px; }
.focus-share i { display: block; height: 3px; border-radius: 9px; opacity: .85; transition: width .3s; }
.focus-share span { font-family: var(--mono); font-size: 9.5px; color: var(--faint); margin-left: auto; }
.mix-strip { display: flex; height: 9px; border-radius: 99px; overflow: hidden; margin-top: 18px; border: 1px solid rgba(255, 255, 255, .05); background: #0a0f16; }
.mix-strip i { display: block; height: 100%; transition: width .35s; }
.mix-legend { display: flex; flex-wrap: wrap; gap: 6px 14px; margin-top: 9px; font-size: 10px; color: var(--faint); }
.mix-legend span { display: flex; align-items: center; gap: 5px; }
.mix-legend i { width: 6px; height: 6px; border-radius: 2px; }
.mix-legend b { color: var(--muted); font-family: var(--mono); font-size: 9.5px; }
.mix-legend small { font-size: 8.5px; color: var(--faint); text-transform: uppercase; letter-spacing: .08em; }

.fit-panel .fit-big { margin: 4px 0 14px; }
.fit-big b { font-family: var(--mono); font-size: 44px; font-weight: 700; letter-spacing: -.04em; color: var(--score, #5eead4); line-height: 1; }
.fit-big b span { font-size: 20px; opacity: .65; margin-left: 2px; }
.fit-bar { height: 8px; border-radius: 99px; background: #0a0f16; overflow: hidden; margin-top: 10px; border: 1px solid rgba(255, 255, 255, .04); }
.fit-bar i { display: block; height: 100%; border-radius: 99px; background: linear-gradient(90deg, var(--c1), var(--c2)); transition: width .3s; }
.tag-list { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 13px; }
.forecast { display: flex; align-items: baseline; gap: 7px; }
.forecast b { font-family: var(--mono); font-size: 32px; letter-spacing: -.03em; font-weight: 700; }
.forecast span { color: var(--faint); font-size: 13px; }
.forecast-meta { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-top: 14px; }
.forecast-meta > div { padding: 8px 10px; border-radius: 9px; background: rgba(255, 255, 255, .025); border: 1px solid var(--line); }
.forecast-meta small { display: block; color: var(--faint); font-size: 9px; text-transform: uppercase; letter-spacing: .08em; margin-bottom: 2px; }
.forecast-meta b { font-family: var(--mono); font-size: 12.5px; }
.action-stack { display: flex; flex-direction: column; gap: 6px; }
.action-row {
  display: flex; align-items: center; gap: 11px; width: 100%; padding: 10px 11px; text-align: left;
  background: rgba(255, 255, 255, .022); border: 1px solid var(--line); border-radius: 10px;
  color: var(--text); cursor: pointer; transition: .15s;
}
.action-row:hover:not(:disabled) { background: rgba(255, 255, 255, .05); border-color: var(--line2); }
.action-row:disabled { opacity: .5; cursor: not-allowed; }
.action-row .action-ic { width: 30px; height: 30px; flex: none; border-radius: 8px; display: grid; place-items: center; color: var(--teal); background: rgba(94, 234, 212, .08); border: 1px solid rgba(94, 234, 212, .14); }
.action-row > span:nth-child(2) { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.action-row b { font-size: 12px; }
.action-row small { color: var(--faint); font-size: 10.5px; margin-top: 1px; }
.action-row em { font-style: normal; font-family: var(--mono); font-size: 8.5px; color: var(--faint); text-transform: uppercase; letter-spacing: .08em; }
.action-row .ic:last-child { color: var(--faint); }
.action-row.on { border-color: rgba(251, 191, 36, .3); background: rgba(251, 191, 36, .05); }
.switch { width: 32px; height: 18px; border-radius: 99px; background: #1a2431; border: 1px solid var(--line2); padding: 2px; flex: none; transition: .2s; }
.switch i { display: block; width: 12px; height: 12px; border-radius: 50%; background: var(--faint); transition: .2s; }
.switch.on { background: rgba(251, 191, 36, .2); border-color: rgba(251, 191, 36, .5); }
.switch.on i { transform: translateX(14px); background: var(--amber); }
.ship-panel { display: flex; align-items: center; gap: 16px; justify-content: space-between; flex-wrap: wrap; }
.ship-panel .ship-copy { flex: 1; min-width: 200px; }
.ship-panel h3 { margin: 4px 0 5px; }
.ship-panel p { color: var(--muted); font-size: 11.5px; line-height: 1.5; }
.ship-panel.ready { border-color: rgba(94, 234, 212, .35); background: linear-gradient(135deg, rgba(94, 234, 212, .08), rgba(167, 139, 250, .04)), var(--panel); box-shadow: 0 0 50px -24px rgba(94, 234, 212, .5); }

