+.col { display: flex; flex-direction: column; gap: 16px; min-width: 0; }
+.focus-list { display: flex; flex-direction: column; gap: 15px; margin-top: 16px; }
+.focus-row { display: flex; flex-direction: column; gap: 7px; }
+.focus-label { display: flex; align-items: center; gap: 7px; font-size: 12px; font-weight: 650; }
+.focus-label .dot { width: 7px; height: 7px; border-radius: 50%; }
+.focus-label small { margin-left: auto; font-family: var(--mono); color: var(--muted); font-size: 10.5px; }
+input[type="range"].slider {
+  -webkit-appearance: none; appearance: none; width: 100%; height: 7px; border-radius: 99px;
+  background: linear-gradient(90deg, var(--accent, #5eead4) var(--v, 50%), #1a2431 var(--v, 50%));
+  outline: none; cursor: pointer; margin: 0;
+}
+input[type="range"].slider::-webkit-slider-thumb {
+  -webkit-appearance: none; width: 17px; height: 17px; border-radius: 50%;
+  background: #f4f9ff; border: 3px solid var(--accent, #5eead4);
+  box-shadow: 0 0 0 4px color-mix(in srgb, var(--accent, #5eead4) 16%, transparent), 0 2px 6px rgba(0, 0, 0, .5);
+  cursor: grab; transition: transform .12s;
+}
+input[type="range"].slider::-webkit-slider-thumb:active { transform: scale(1.12); cursor: grabbing; }
+input[type="range"].slider::-moz-range-thumb { width: 15px; height: 15px; border-radius: 50%; background: #f4f9ff; border: 3px solid var(--accent, #5eead4); }
+.focus-share { display: flex; align-items: center; gap: 8px; }
+.focus-share i { display: block; height: 3px; border-radius: 9px; opacity: .85; transition: width .3s; }
+.focus-share span { font-family: var(--mono); font-size: 9.5px; color: var(--faint); margin-left: auto; }
+.mix-strip { display: flex; height: 9px; border-radius: 99px; overflow: hidden; margin-top: 18px; border: 1px solid rgba(255, 255, 255, .05); background: #0a0f16; }
+.mix-strip i { display: block; height: 100%; transition: width .35s; }
+.mix-legend { display: flex; flex-wrap: wrap; gap: 6px 14px; margin-top: 9px; font-size: 10px; color: var(--faint); }
+.mix-legend span { display: flex; align-items: center; gap: 5px; }
+.mix-legend i { width: 6px; height: 6px; border-radius: 2px; }
+.mix-legend b { color: var(--muted); font-family: var(--mono); font-size: 9.5px; }
+.mix-legend small { font-size: 8.5px; color: var(--faint); text-transform: uppercase; letter-spacing: .08em; }
+
+.fit-panel .fit-big { margin: 4px 0 14px; }
+.fit-big b { font-family: var(--mono); font-size: 44px; font-weight: 700; letter-spacing: -.04em; color: var(--score, #5eead4); line-height: 1; }
+.fit-big b span { font-size: 20px; opacity: .65; margin-left: 2px; }
+.fit-bar { height: 8px; border-radius: 99px; background: #0a0f16; overflow: hidden; margin-top: 10px; border: 1px solid rgba(255, 255, 255, .04); }
+.fit-bar i { display: block; height: 100%; border-radius: 99px; background: linear-gradient(90deg, var(--c1), var(--c2)); transition: width .3s; }
+.tag-list { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 13px; }
+.forecast { display: flex; align-items: baseline; gap: 7px; }
+.forecast b { font-family: var(--mono); font-size: 32px; letter-spacing: -.03em; font-weight: 700; }
+.forecast span { color: var(--faint); font-size: 13px; }
+.forecast-meta { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-top: 14px; }
+.forecast-meta > div { padding: 8px 10px; border-radius: 9px; background: rgba(255, 255, 255, .025); border: 1px solid var(--line); }
+.forecast-meta small { display: block; color: var(--faint); font-size: 9px; text-transform: uppercase; letter-spacing: .08em; margin-bottom: 2px; }
+.forecast-meta b { font-family: var(--mono); font-size: 12.5px; }
+.action-stack { display: flex; flex-direction: column; gap: 6px; }
+.action-row {
+  display: flex; align-items: center; gap: 11px; width: 100%; padding: 10px 11px; text-align: left;
+  background: rgba(255, 255, 255, .022); border: 1px solid var(--line); border-radius: 10px;
+  color: var(--text); cursor: pointer; transition: .15s;
+}
+.action-row:hover:not(:disabled) { background: rgba(255, 255, 255, .05); border-color: var(--line2); }
+.action-row:disabled { opacity: .5; cursor: not-allowed; }
+.action-row .action-ic { width: 30px; height: 30px; flex: none; border-radius: 8px; display: grid; place-items: center; color: var(--teal); background: rgba(94, 234, 212, .08); border: 1px solid rgba(94, 234, 212, .14); }
+.action-row > span:nth-child(2) { flex: 1; min-width: 0; display: flex; flex-direction: column; }
+.action-row b { font-size: 12px; }
+.action-row small { color: var(--faint); font-size: 10.5px; margin-top: 1px; }
+.action-row em { font-style: normal; font-family: var(--mono); font-size: 8.5px; color: var(--faint); text-transform: uppercase; letter-spacing: .08em; }
+.action-row .ic:last-child { color: var(--faint); }
+.action-row.on { border-color: rgba(251, 191, 36, .3); background: rgba(251, 191, 36, .05); }
+.switch { width: 32px; height: 18px; border-radius: 99px; background: #1a2431; border: 1px solid var(--line2); padding: 2px; flex: none; transition: .2s; }
+.switch i { display: block; width: 12px; height: 12px; border-radius: 50%; background: var(--faint); transition: .2s; }
+.switch.on { background: rgba(251, 191, 36, .2); border-color: rgba(251, 191, 36, .5); }
+.switch.on i { transform: translateX(14px); background: var(--amber); }
+.ship-panel { display: flex; align-items: center; gap: 16px; justify-content: space-between; flex-wrap: wrap; }
+.ship-panel .ship-copy { flex: 1; min-width: 200px; }
+.ship-panel h3 { margin: 4px 0 5px; }
+.ship-panel p { color: var(--muted); font-size: 11.5px; line-height: 1.5; }
+.ship-panel.ready { border-color: rgba(94, 234, 212, .35); background: linear-gradient(135deg, rgba(94, 234, 212, .08), rgba(167, 139, 250, .04)), var(--panel); box-shadow: 0 0 50px -24px rgba(94, 234, 212, .5); }

input.newString:
.ship-panel.ready { border-color: rgba(94, 234, 212, .35); background: linear-gradient(135deg, rgba(94, 234, 212, .08), rgba(167, 139, 250, .04)), var(--panel); box-shadow: 0 0 50px -24px rgba(94, 234, 212, .5); }

/* ---------------- team ---------------- */
.team-grid { display: grid; grid-template-columns: minmax(0, 1.5fr) minmax(300px, 1fr); gap: 16px; align-items: start; }
.staff-list { display: flex; flex-direction: column; gap: 8px; }
.staff-card {
  display: flex; align-items: center; gap: 13px; padding: 12px;
  border-radius: 12px; border: 1px solid var(--line); background: rgba(255, 255, 255, .02);
  transition: .15s;
}
.staff-card:hover { border-color: var(--line2); background: rgba(255, 255, 255, .035); }
.avatar {
  width: 40px; height: 40px; flex: none; border-radius: 11px; display: grid; place-items: center;
  font-family: var(--mono); font-size: 11.5px; font-weight: 700; color: #071018;
  background: linear-gradient(135deg, var(--c, #5eead4), color-mix(in srgb, var(--c, #5eead4) 55%, #0b1017));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .35);
}
.avatar.lg { width: 48px; height: 48px; border-radius: 13px; font-size: 13px; }
.avatar.ghost { background: transparent; border: 1px dashed var(--line2); color: var(--faint); box-shadow: none; }
.staff-info { flex: 1; min-width: 0; }
.staff-name { font-size: 13px; font-weight: 650; display: flex; align-items: center; gap: 7px; }
.staff-role { font-size: 10.5px; font-weight: 600; margin-top: 1px; }
.staff-skill { display: flex; align-items: center; gap: 8px; margin-top: 7px; }
.staff-skill b { font-family: var(--mono); font-size: 10px; color: var(--muted); }
.pips { display: flex; gap: 2px; }
.pips i { width: 4px; height: 10px; border-radius: 2px; background: #1d2937; }
.pips i.on { background: linear-gradient(180deg, var(--teal), #38bdf8); box-shadow: 0 0 5px rgba(94, 234, 212, .4); }
.staff-morale { display: flex; align-items: center; gap: 7px; margin-top: 7px; }
.staff-morale > span { font-size: 9px; color: var(--faint); text-transform: uppercase; letter-spacing: .08em; }
.staff-morale .bar { flex: 1; max-width: 130px; }
.staff-morale b { font-family: var(--mono); font-size: 9.5px; color: var(--muted); }
.staff-actions { display: flex; flex-direction: column; align-items: flex-end; gap: 6px; flex: none; }
.staff-actions .cost { font-family: var(--mono); font-size: 8.5px; color: var(--faint); }
.empty-slot { border-style: dashed; opacity: .55; }
.hire-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.hire-card { padding: 11px; border-radius: 11px; border: 1px solid var(--line); background: rgba(255, 255, 255, .022); display: flex; flex-direction: column; gap: 9px; }
.hire-top { display: flex; align-items: center; gap: 8px; }
.hire-top > div { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.hire-top b { font-size: 11.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.hire-top small { font-size: 9.5px; font-weight: 600; }
.skill-badge { font-family: var(--mono); font-size: 11px; font-weight: 700; color: var(--teal); background: rgba(94, 234, 212, .08); border: 1px solid rgba(94, 234, 212, .2); border-radius: 6px; padding: 2px 6px; }
.hire-meta { display: flex; justify-content: space-between; gap: 4px; font-family: var(--mono); font-size: 8.5px; color: var(--faint); }
.office-upgrade .office-ill { display: flex; align-items: center; gap: 13px; padding: 14px; border-radius: 11px; background: radial-gradient(circle at 10% 20%, rgba(94, 234, 212, .09), transparent 60%), rgba(255, 255, 255, .02); border: 1px solid var(--line); color: var(--teal); }
.office-ill > div { display: flex; flex-direction: column; gap: 2px; }
.office-ill b { color: var(--text); font-size: 13px; }
.office-ill small { color: var(--faint); font-size: 10.5px; }
.upgrade-next .metric-top { margin-bottom: 4px; }
.role-list { display: flex; flex-direction: column; gap: 8px; margin-top: 13px; }
.role-row { display: flex; align-items: center; gap: 8px; }
.role-row b { font-size: 11.5px; width: 78px; }
.role-dot { width: 7px; height: 7px; border-radius: 50%; flex: none; }
.role-bars { display: flex; align-items: flex-end; gap: 3px; height: 24px; margin-left: auto; }
.role-bars i { width: 8px; border-radius: 2px; opacity: .8; }
.role-legend { display: flex; gap: 12px; margin-top: 9px; font-family: var(--mono); font-size: 8.5px; color: var(--faint); }
.role-legend span { display: flex; align-items: center; gap: 4px; }
.role-legend i { width: 6px; height: 6px; border-radius: 2px; }

/* ---------------- market ---------------- */
.trend-panel { display: flex; align-items: center; justify-content: space-between; gap: 20px; margin-bottom: 22px; overflow: hidden; }
.trend-panel::after { content: ""; position: absolute; right: -60px; top: -100px; width: 320px; height: 320px; border-radius: 50%; background: radial-gradient(circle, rgba(167, 139, 250, .18), transparent 65%); pointer-events: none; }
.trend-copy h2 { font-size: 24px; margin: 4px 0 4px; letter-spacing: -.03em; }
.trend-copy .amp { color: var(--faint); font-weight: 400; }
.trend-chips { display: flex; gap: 7px; flex-wrap: wrap; position: relative; z-index: 1; }
.section-head { display: flex; align-items: baseline; gap: 12px; margin: 26px 0 12px; flex-wrap: wrap; }
.section-head h2 { display: flex; align-items: center; gap: 8px; }
.section-head .muted { font-size: 11.5px; }
.platform-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(228px, 1fr)); gap: 12px; }
.platform-card { padding: 14px; border-radius: 13px; border: 1px solid var(--line); background: linear-gradient(180deg, rgba(255, 255, 255, .025), transparent 55%), var(--panel); display: flex; flex-direction: column; gap: 11px; transition: .18s; }
.platform-card:hover { border-color: var(--line2); transform: translateY(-2px); }
.platform-card.owned { border-color: rgba(94, 234, 212, .22); }
.pc-head { display: flex; align-items: center; gap: 10px; }
.pc-mono {
  width: 40px; height: 40px; flex: none; border-radius: 10px; display: grid; place-items: center;
  font-family: var(--mono); font-size: 11px; font-weight: 800; color: #06121a;
  background: linear-gradient(135deg, var(--c1), var(--c2)); box-shadow: inset 0 1px 0 rgba(255, 255, 255, .4);
}
.pc-head > div { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.pc-head b { font-size: 13px; }
.pc-head small { color: var(--faint); font-size: 9.5px; text-transform: capitalize; }
.pc-metrics { display: flex; flex-direction: column; gap: 6px; }
.pc-metrics > div { display: grid; grid-template-columns: 40px 1fr 30px; align-items: center; gap: 7px; }
.pc-metrics span { font-size: 9.5px; color: var(--faint); text-transform: uppercase; letter-spacing: .07em; }
.pc-metrics b { font-family: var(--mono); font-size: 9.5px; text-align: right; color: var(--muted); }
.pc-facts { display: flex; gap: 12px; flex-wrap: wrap; font-size: 9.5px; color: var(--faint); }
.pc-facts span { display: flex; align-items: center; gap: 4px; }
.pc-note { font-size: 10.5px; color: var(--muted); line-height: 1.45; margin: 0; }
.pc-owned { display: flex; align-items: center; gap: 5px; font-size: 10px; color: var(--teal); font-weight: 600; padding-top: 2px; }
.engine-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); gap: 12px; }
.engine-card { padding: 14px; border-radius: 13px; border: 1px solid var(--line); background: var(--panel); display: flex; flex-direction: column; gap: 10px; }
.engine-card.owned { border-color: rgba(167, 139, 250, .25); }
.engine-top { display: flex; align-items: center; gap: 9px; }
.engine-glyph { width: 34px; height: 34px; border-radius: 9px; display: grid; place-items: center; color: var(--violet); background: rgba(167, 139, 250, .08); border: 1px solid rgba(167, 139, 250, .18); flex: none; }
.engine-top > div { flex: 1; min-width: 0; }
.engine-top b { display: block; font-size: 12.5px; }
.engine-top small { color: var(--faint); font-size: 9.5px; }
.engine-stats { display: flex; gap: 16px; }
.engine-stats small { display: block; color: var(--faint); font-size: 8.5px; text-transform: uppercase; letter-spacing: .08em; }
.engine-stats b { font-family: var(--mono); font-size: 14px; color: var(--violet); }
.upgrade-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 12px; }
.upgrade-card { padding: 14px; border-radius: 13px; border: 1px solid var(--line); background: var(--panel); display: flex; flex-direction: column; gap: 6px; }
.upgrade-card.owned { border-color: rgba(94, 234, 212, .22); }
.upgrade-top { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.upgrade-tag { font-family: var(--mono); font-size: 8px; letter-spacing: .12em; text-transform: uppercase; color: var(--faint); border: 1px solid var(--line); border-radius: 5px; padding: 2px 5px; }
.upgrade-card > b { font-size: 12.5px; margin-top: 2px; }
.upgrade-card p { font-size: 10.5px; color: var(--muted); line-height: 1.45; margin: 0 0 4px; }

/* ---------------- releases ---------------- */
.stat-strip { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-bottom: 16px; }
.chart-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px; margin-bottom: 16px; }
.chart-wrap { border-radius: 13px; border: 1px solid var(--line); background: var(--panel); padding: 14px; }
.chart-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; margin-bottom: 8px; }
.chart-head span { font-size: 10px; letter-spacing: .1em; text-transform: uppercase; color: var(--faint); }
.chart-head b { font-family: var(--mono); font-size: 15px; }
.chart { width: 100%; height: 108px; display: block; }
.chart-axis { display: flex; justify-content: space-between; font-family: var(--mono); font-size: 8px; color: var(--faint); margin-top: 3px; }
.release-list { display: flex; flex-direction: column; gap: 8px; }
.release-card { display: flex; align-items: center; gap: 14px; padding: 12px; border-radius: 12px; border: 1px solid var(--line); background: rgba(255, 255, 255, .02); }
.release-card:hover { background: rgba(255, 255, 255, .035); }
.score-badge {
  width: 62px; height: 62px; flex: none; border-radius: 12px; display: flex; flex-direction: column; align-items: center; justify-content: center;
  border: 1px solid color-mix(in srgb, var(--score) 35%, transparent);
  background: linear-gradient(180deg, color-mix(in srgb, var(--score) 16%, transparent), color-mix(in srgb, var(--score) 4%, transparent));
}
.score-badge b { font-family: var(--mono); font-size: 21px; color: var(--score); line-height: 1; }
.score-badge small { font-size: 8px; text-transform: uppercase; letter-spacing: .06em; color: var(--score); opacity: .75; margin-top: 3px; }
.release-main { flex: 1; min-width: 0; }
.release-title { display: flex; align-items: center; gap: 8px; font-size: 14px; font-weight: 650; margin-bottom: 5px; }
.goty-tag { display: inline-flex; align-items: center; gap: 3px; font-family: var(--mono); font-size: 8px; letter-spacing: .1em; color: var(--amber); border: 1px solid rgba(251, 191, 36, .35); background: rgba(251, 191, 36, .08); border-radius: 5px; padding: 2px 5px; }
.release-meta { display: flex; flex-wrap: wrap; gap: 4px 14px; margin-top: 7px; font-size: 10px; color: var(--faint); }
.release-side { display: flex; flex-direction: column; align-items: flex-end; gap: 6px; flex: none; }
.release-paid { font-family: var(--mono); font-size: 10px; color: var(--muted); }

