.marketing-block .metric-top b { color: var(--amber); font-size: 14px; }
input[type="range"].marketing { --accent: #fbbf24; background: linear-gradient(90deg, #fbbf24 var(--v, 20%), #1a2431 var(--v, 20%)); }
.marketing-scale { display: flex; justify-content: space-between; font-family: var(--mono); font-size: 8px; color: var(--faint); margin-top: 5px; }
.wiz-notes { display: flex; flex-wrap: wrap; gap: 7px 14px; margin-top: 12px; font-size: 9.5px; color: var(--faint); }
.wiz-notes span { display: flex; align-items: center; gap: 4px; }
.wizard-foot { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-top: 18px; padding-top: 14px; border-top: 1px solid var(--line); }
.wiz-cash { display: flex; align-items: center; gap: 6px; font-family: var(--mono); font-size: 11px; color: var(--muted); }
.wiz-buttons { display: flex; gap: 7px; }

/* ---------------- toasts ---------------- */
#toast-root { position: fixed; right: 18px; bottom: 18px; z-index: 200; display: flex; flex-direction: column; gap: 7px; align-items: flex-end; pointer-events: none; max-width: min(360px, calc(100vw - 28px)); }
.toast {
  display: flex; align-items: flex-start; gap: 9px; padding: 10px 13px; border-radius: 10px;
  background: rgba(18, 26, 37, .96); border: 1px solid #2d3d51; color: #c9d6e6;
  font-size: 11.5px; line-height: 1.4; box-shadow: 0 16px 40px -14px #000;
  animation: toastIn .28s cubic-bezier(.2, .9, .3, 1.1); backdrop-filter: blur(12px);
}
.toast.out { animation: toastOut .3s forwards; }
.toast-ic { color: var(--muted); flex: none; margin-top: 1px; }
.toast.good { border-color: rgba(94, 234, 212, .3); }
.toast.good .toast-ic { color: var(--teal); }
.toast.bad { border-color: rgba(251, 113, 133, .35); }
.toast.bad .toast-ic { color: var(--red); }
.toast.warn { border-color: rgba(251, 191, 36, .3); }
.toast.warn .toast-ic { color: var(--amber); }
@keyframes toastIn { from { opacity: 0; transform: translateY(10px) scale(.97); } to { opacity: 1; transform: none; } }
@keyframes toastOut { to { opacity: 0; transform: translateX(20px); } }

/* ---------------- svg ambient ---------------- */
.dev { animation: bob 3.4s ease-in-out infinite; transform-origin: center; }
.scan { animation: scan 4s linear infinite; }
@keyframes bob { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-2px); } }
@keyframes scan { 0% { transform: translateY(0); opacity: 0; } 10% { opacity: .14; } 50% { transform: translateY(28px); opacity: 0; } 100% { transform: translateY(28px); opacity: 0; } }

/* ---------------- responsive ---------------- */
@media (max-width: 1180px) {
  .studio-grid { grid-template-columns: minmax(0, 1.45fr) minmax(290px, 1fr); }
  .hire-grid { grid-template-columns: 1fr; }
  .pick-grid.genres { grid-template-columns: repeat(4, 1fr); }
}
@media (max-width: 1020px) {
  #shell { grid-template-columns: 200px minmax(0, 1fr); }
  .brand { width: 168px; }
  #main { padding: 20px 18px 48px; }
  .studio-grid, .detail-grid, .team-grid { grid-template-columns: 1fr; }
  .office-panel, .pulse-panel, .project-summary, .news-panel { grid-column: 1; }
  .news-list { max-height: 260px; }
  .chart-grid { grid-template-columns: 1fr; }
  .summary-grid { grid-template-columns: repeat(4, 1fr); }
  .t-float { display: none; }
}
@media (max-width: 860px) {
  #shell { grid-template-columns: 1fr; grid-template-rows: auto minmax(0, 1fr) auto; }
  #topbar { grid-row: 1; grid-column: 1; flex-wrap: wrap; gap: 8px; padding: 8px 12px; }
  .brand { width: auto; }
  .brand-text span { display: none; }
  .topstats { order: 3; flex-basis: 100%; padding: 2px 0 3px; gap: 2px; }
  .stat { padding: 4px 8px; }
  .stat-week { padding-right: 10px; margin-right: 2px; }
  .stat-txt b { font-size: 11.5px; }
  .top-actions { margin-left: auto; gap: 6px; }
  .advance-btn { width: 40px; padding: 0; height: 38px; }
  .advance-btn .adv-label, .advance-btn kbd { display: none; }
  #sidebar { display: none; }
  #main { grid-row: 2; grid-column: 1; padding: 14px 12px 26px; }
  #bottomnav {
    grid-row: 3; grid-column: 1; display: flex; align-items: stretch;
    background: rgba(9, 13, 19, .96); border-top: 1px solid var(--line);
    padding: 5px 6px calc(5px + env(safe-area-inset-bottom)); backdrop-filter: blur(16px);
  }
  .bn-item {
    flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 3px;
    background: none; border: none; color: var(--faint); font-size: 8.5px; font-weight: 600;
    padding: 5px 2px; border-radius: 8px; cursor: pointer; min-height: 46px; position: relative;
  }
  .bn-item.active { color: var(--teal); }
  .bn-item.active::before { content: ""; position: absolute; top: 0; width: 22px; height: 2px; border-radius: 9px; background: var(--teal); box-shadow: 0 0 10px var(--teal); }
  .bn-ic { display: grid; place-items: center; position: relative; }
  .bn-ic .nav-dot { position: absolute; top: -1px; right: -4px; margin: 0; width: 5px; height: 5px; }
  .view-head h1 { font-size: 24px; }
  .view-head { margin-bottom: 14px; }
  .panel { padding: 14px; border-radius: 14px; }
  .office-panel { padding: 0; }
  .office-svg { min-height: 150px; object-fit: cover; }
  .office-overlay.top { top: 8px; left: 8px; right: 8px; }
  .office-overlay .chip { height: 23px; font-size: 9.5px; }
  .summary-grid, .stat-row { grid-template-columns: repeat(2, 1fr); }
  .stat-strip { grid-template-columns: repeat(2, 1fr); }
  .stat-strip .stat-box b { font-size: 15px; }
  .head-actions { width: 100%; }
  .head-actions .btn { flex: 1; }
  .modal-backdrop { padding: 0; align-items: flex-end; }
  .modal { width: 100%; max-height: 94dvh; border-radius: 20px 20px 0 0; padding: 18px; border-bottom: none; }
  .modal.wide, .modal.narrow { width: 100%; }
  .results-hero { flex-direction: column; align-items: flex-start; gap: 14px; }
  .score-ring { width: 104px; height: 104px; align-self: center; }
  .score-num b { font-size: 30px; }
  .results-copy { text-align: center; }
  .results-copy .chips { justify-content: center; }
  .result-stats { grid-template-columns: repeat(2, 1fr); }
  .help-grid { grid-template-columns: 1fr; }
  .pick-grid.genres { grid-template-columns: repeat(2, 1fr); }
  .pick-grid.themes { grid-template-columns: repeat(3, 1fr); }
  .wiz-platforms { grid-template-columns: 1fr; }
  .scope-grid { grid-template-columns: repeat(2, 1fr); }
  .wiz-facts { grid-template-columns: repeat(2, 1fr); }
  .wizard-foot { position: sticky; bottom: -18px; background: linear-gradient(180deg, rgba(13, 20, 29, .7), #0d141d 35%); margin: 18px -18px -18px; padding: 12px 18px calc(12px + env(safe-area-inset-bottom)); }
  #toast-root { bottom: calc(70px + env(safe-area-inset-bottom)); right: 10px; left: 10px; max-width: none; align-items: stretch; }
  .toast { width: 100%; }
  .trend-panel { flex-direction: column; align-items: flex-start; gap: 10px; }
  .trend-copy h2 { font-size: 20px; }
  .hire-grid { grid-template-columns: 1fr; }
  .staff-card { flex-wrap: wrap; }
  .staff-actions { flex-direction: row; align-items: center; width: 100%; justify-content: flex-end; }
  .release-card { flex-wrap: wrap; }
  .release-side { flex-direction: row; align-items: center; width: 100%; justify-content: space-between; }
  .platform-grid, .engine-grid, .upgrade-grid { grid-template-columns: 1fr; }
  .chart-grid { grid-template-columns: 1fr; }
  .project-summary.empty-project { flex-direction: column; align-items: flex-start; text-align: left; }
  .ship-panel { flex-direction: column; align-items: stretch; }
  .ship-panel .btn { width: 100%; }
  .t-features { display: none; }
  .t-card { padding: 18px; }
  .t-logo { gap: .1em; }
  #title-screen { padding: 22px 14px 60px; align-items: center; }
  .t-foot { position: static; margin-top: 22px; }
}
@media (max-width: 480px) {
  .brand-text strong { font-size: 11px; }
  .brand-mark, .brand-mark svg { width: 30px; height: 30px; }
  .icon-btn { width: 36px; height: 36px; }
  .advance-btn { width: 36px; height: 36px; }
  .top-actions { gap: 4px; }
  .stat { padding: 3px 6px; gap: 5px; }
  .stat-ic { display: none; }
  .stat-week .stat-ic { display: grid; }
  .stat-txt b { font-size: 11px; }
  .stat-txt small { font-size: 7.5px; }
  .chip { font-size: 10.5px; }
  .view-head h1 { font-size: 22px; }
  .view-head .sub { font-size: 12px; }
  .panel-head h2 { font-size: 16px; }
  .office-foot .mini-name { display: none; }
  .pick-grid.themes { grid-template-columns: repeat(2, 1fr); }
  .wiz-title-input input { font-size: 14px; }
  .modal-actions .btn { flex: 1; }
  .results-copy h2 { font-size: 22px; }
  .award-modal h2 { font-size: 24px; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .001ms !important; animation-iteration-count: 1 !important; transition-duration: .001ms !important; }
}

