--- css/styles.css
+++ css/styles.css
@@ -602,4 +602,314 @@
 .goty-tag { display: inline-flex; align-items: center; gap: 3px; font-family: var(--mono); font-size: 8px; letter-spacing: .1em; color: var(--amber); border: 1px solid rgba(251, 191, 36, .35); background: rgba(251, 191, 36, .08); border-radius: 5px; padding: 2px 5px; }
 .release-meta { display: flex; flex-wrap: wrap; gap: 4px 14px; margin-top: 7px; font-size: 10px; color: var(--faint); }
 .release-side { display: flex; flex-direction: column; align-items: flex-end; gap: 6px; flex: none; }
 .release-paid { font-family: var(--mono); font-size: 10px; color: var(--muted); }
+
+/* ---------------- modals ---------------- */
+#modal-root { position: fixed; inset: 0; z-index: 100; pointer-events: none; }
+#modal-root.open { pointer-events: auto; }
+.modal-backdrop {
+  position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; padding: 24px;
+  background: rgba(3, 6, 10, .74); backdrop-filter: blur(10px); opacity: 0; transition: opacity .2s ease;
+}
+#modal-root.open .modal-backdrop { opacity: 1; }
+.modal {
+  width: min(720px, 100%); max-height: min(92dvh, 940px); overflow-y: auto; position: relative;
+  background: linear-gradient(180deg, #151e2a, #0d141d); border: 1px solid #2a394b;
+  border-radius: 20px; box-shadow: 0 50px 120px -20px #000, inset 0 1px 0 rgba(255, 255, 255, .05);
+  transform: translateY(14px) scale(.985); transition: transform .26s cubic-bezier(.2, .9, .25, 1.05);
+  padding: 22px;
+}
+#modal-root.open .modal { transform: none; }
+.modal.wide { width: min(880px, 100%); }
+.modal.narrow { width: min(470px, 100%); }
+.modal-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; margin-bottom: 18px; }
+.modal-head h2 { margin-top: 3px; font-size: 22px; }
+.modal-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 20px; flex-wrap: wrap; }
+.modal-actions .btn-primary { min-width: 170px; }
+.modal .icon-btn { flex: none; }
+
+.results-hero { display: flex; align-items: center; gap: 22px; }
+.score-ring { position: relative; width: 136px; height: 136px; flex: none; }
+.score-ring svg { width: 100%; height: 100%; }
+.score-num { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; }
+.score-num b { font-family: var(--mono); font-size: 38px; line-height: 1; color: var(--score); letter-spacing: -.05em; }
+.score-num small { font-size: 8.5px; text-transform: uppercase; letter-spacing: .14em; color: var(--score); opacity: .75; margin-top: 4px; }
+.results-copy { min-width: 0; }
+.results-copy h2 { font-size: 26px; margin: 4px 0 9px; letter-spacing: -.035em; }
+.results-lede { color: var(--muted); font-size: 12.5px; line-height: 1.55; margin-top: 12px; }
+.critic-list { display: flex; flex-direction: column; gap: 7px; margin-top: 20px; }
+.critic-row { display: flex; gap: 11px; padding: 10px 12px; border-radius: 10px; background: rgba(255, 255, 255, .022); border: 1px solid var(--line); }
+.critic-av { width: 32px; height: 32px; border-radius: 8px; flex: none; display: grid; place-items: center; font-family: var(--mono); font-size: 9px; font-weight: 700; color: #071018; background: linear-gradient(135deg, #5eead4, #38bdf8); }
+.critic-body { flex: 1; min-width: 0; }
+.critic-body > div { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; }
+.critic-body b { font-size: 11.5px; }
+.critic-score { font-family: var(--mono); font-size: 13px; font-weight: 700; }
+.critic-body p { font-size: 10.5px; color: var(--muted); line-height: 1.45; margin-top: 2px; font-style: italic; }
+.result-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; margin-top: 18px; }
+.result-stats > div { padding: 10px 12px; border-radius: 10px; background: rgba(255, 255, 255, .025); border: 1px solid var(--line); }
+.result-stats small { display: block; color: var(--faint); font-size: 9px; text-transform: uppercase; letter-spacing: .08em; margin-bottom: 3px; }
+.result-stats b { font-family: var(--mono); font-size: 15px; }
+.results-foot { color: var(--faint); font-size: 10.5px; line-height: 1.5; margin-top: 14px; }
+.confetti { position: absolute; inset: 0; pointer-events: none; overflow: hidden; border-radius: 20px; }
+.confetti i { position: absolute; top: -12px; left: var(--x); width: 7px; height: 11px; background: var(--c); border-radius: 1px; transform: rotate(var(--r)); animation: fall 2.8s linear var(--d) forwards; opacity: 0; }
+@keyframes fall { 0% { opacity: 0; translate: 0 -10px; } 8% { opacity: 1; } 100% { opacity: 0; translate: 0 560px; rotate: 240deg; } }
+
+.award-modal { text-align: center; padding: 14px 8px 4px; }
+.award-trophy { width: 104px; height: 104px; margin: 0 auto 14px; border-radius: 50%; display: grid; place-items: center; color: var(--amber); background: radial-gradient(circle, rgba(251, 191, 36, .2), transparent 70%); border: 1px solid rgba(251, 191, 36, .25); box-shadow: 0 0 60px -10px rgba(251, 191, 36, .45); }
+.award-modal h2 { font-size: 30px; letter-spacing: -.04em; margin: 4px 0 6px; }
+.award-title { font-family: var(--mono); font-size: 16px; color: var(--amber); }
+.award-score { font-family: var(--mono); font-size: 34px; font-weight: 700; margin-top: 10px; }
+.award-score small { font-size: 12px; color: var(--faint); }
+.award-modal .results-lede { max-width: 420px; margin-left: auto; margin-right: auto; }
+.award-modal .modal-actions { justify-content: center; }
+
+.gameover-modal { text-align: center; padding: 10px 6px; }
+.go-icon { width: 80px; height: 80px; margin: 0 auto 12px; border-radius: 50%; display: grid; place-items: center; color: var(--red); background: rgba(251, 113, 133, .08); border: 1px solid rgba(251, 113, 133, .25); }
+.gameover-modal h2 { font-size: 28px; margin: 4px 0 6px; letter-spacing: -.04em; }
+.gameover-modal .result-stats { grid-template-columns: repeat(2, 1fr); }
+.gameover-modal .modal-actions { justify-content: center; }
+
+.help-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; }
+.help-step { display: flex; gap: 11px; padding: 12px; border-radius: 11px; background: rgba(255, 255, 255, .022); border: 1px solid var(--line); }
+.help-step > span { font-family: var(--mono); font-size: 10px; color: var(--teal); border: 1px solid rgba(94, 234, 212, .25); border-radius: 6px; height: 22px; padding: 0 6px; display: grid; place-items: center; flex: none; }
+.help-step b { font-size: 12px; }
+.help-step p { font-size: 10.5px; color: var(--muted); line-height: 1.5; margin-top: 3px; }
+.help-tips { margin-top: 16px; padding: 14px; border-radius: 11px; background: rgba(94, 234, 212, .04); border: 1px solid rgba(94, 234, 212, .14); }
+.help-tips > b { font-size: 12px; color: var(--teal); }
+.help-tips ul { margin: 8px 0 0; padding-left: 18px; }
+.help-tips li { font-size: 11px; color: var(--muted); line-height: 1.6; }
+.menu-list { display: flex; flex-direction: column; gap: 6px; }
+.menu-modal .tiny-note { text-align: center; margin-top: 16px; }
+.confirm-modal h2 { font-size: 21px; margin-bottom: 8px; letter-spacing: -.03em; }
+.confirm-modal .modal-actions { justify-content: flex-end; }
+
+/* ---------------- wizard ---------------- */
+.wizard-head { margin-bottom: 10px; }
+.step-dots { display: flex; gap: 5px; margin-bottom: 18px; }
+.step-dots i { height: 3px; flex: 1; border-radius: 9px; background: #1c2836; transition: .25s; }
+.step-dots i.on { background: linear-gradient(90deg, #5eead4, #38bdf8); box-shadow: 0 0 10px -2px rgba(94, 234, 212, .6); }
+.wiz-title-row { margin-bottom: 18px; }
+.wiz-title-row > label { display: block; font-family: var(--mono); font-size: 9px; letter-spacing: .16em; color: var(--faint); margin-bottom: 7px; }
+.wiz-title-input { display: flex; gap: 7px; }
+.wiz-title-input input {
+  flex: 1; height: 46px; padding: 0 14px; border-radius: 10px; border: 1px solid #2b3a4d;
+  background: #0a1018; color: var(--text); font-size: 16px; font-weight: 650; letter-spacing: -.01em;
+}
+.wiz-title-input input:focus { outline: none; border-color: rgba(94, 234, 212, .5); box-shadow: 0 0 0 3px rgba(94, 234, 212, .08); }
+.wiz-section { margin-bottom: 16px; }
+.wiz-label { font-family: var(--mono); font-size: 9px; letter-spacing: .16em; color: var(--faint); margin-bottom: 7px; }
+.pick-grid { display: grid; gap: 6px; }
+.pick-grid.genres { grid-template-columns: repeat(4, 1fr); }
+.pick-grid.themes { grid-template-columns: repeat(4, 1fr); }
+.pick {
+  display: flex; flex-direction: column; align-items: flex-start; gap: 1px; padding: 8px 9px;
+  border-radius: 9px; border: 1px solid var(--line); background: rgba(255, 255, 255, .02);
+  color: var(--text); cursor: pointer; text-align: left; transition: .14s; min-width: 0;
+}
+.pick:hover { background: rgba(255, 255, 255, .05); border-color: var(--line2); }
+.pick.on { border-color: color-mix(in srgb, var(--c1) 65%, transparent); background: linear-gradient(135deg, color-mix(in srgb, var(--c1) 16%, transparent), color-mix(in srgb, var(--c2) 6%, transparent)); box-shadow: 0 0 0 1px color-mix(in srgb, var(--c1) 35%, transparent); }
+.pick-mono { width: 24px; height: 20px; border-radius: 5px; display: grid; place-items: center; font-family: var(--mono); font-size: 7.5px; font-weight: 800; color: #06121a; background: linear-gradient(135deg, var(--c1), var(--c2)); margin-bottom: 4px; }
+.pick-name { font-size: 11px; font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
+.pick small { font-size: 8.5px; color: var(--faint); }
+.pick.theme { flex-direction: row; align-items: center; gap: 6px; padding: 7px 8px; }
+.pick.theme .pick-mono { margin: 0; flex: none; }
+.pick.theme .pick-name { font-size: 10px; }
+.synergy-banner { display: flex; gap: 10px; padding: 11px 13px; border-radius: 10px; background: rgba(255, 255, 255, .025); border: 1px solid var(--line); margin-top: 4px; }
+.synergy-banner.good { background: rgba(94, 234, 212, .05); border-color: rgba(94, 234, 212, .22); }
+.synergy-banner.bad { background: rgba(251, 113, 133, .05); border-color: rgba(251, 113, 133, .22); }
+.syn-icon { color: var(--muted); flex: none; margin-top: 1px; }
+.synergy-banner.good .syn-icon { color: var(--teal); }
+.synergy-banner.bad .syn-icon { color: var(--red); }
+.synergy-banner b { font-size: 11.5px; }
+.synergy-banner p { font-size: 10.5px; color: var(--muted); line-height: 1.45; margin-top: 2px; }
+.wiz-platforms { display: grid; grid-template-columns: repeat(2, 1fr); gap: 6px; }
+.wiz-platform {
+  display: flex; align-items: center; gap: 8px; padding: 8px 10px; border-radius: 9px;
+  border: 1px solid var(--line); background: rgba(255, 255, 255, .02); color: var(--text);
+  cursor: pointer; text-align: left; transition: .14s; position: relative;
+}
+.wiz-platform:hover:not(:disabled) { background: rgba(255, 255, 255, .05); }
+.wiz-platform.on { border-color: color-mix(in srgb, var(--c1) 60%, transparent); background: color-mix(in srgb, var(--c1) 9%, transparent); box-shadow: 0 0 0 1px color-mix(in srgb, var(--c1) 30%, transparent); }
+.wiz-platform.locked { opacity: .42; cursor: not-allowed; }
+.wiz-platform .pick-mono { margin: 0; }
+.wp-name { flex: 1; min-width: 0; display: flex; flex-direction: column; font-size: 11px; font-weight: 650; }
+.wp-name small { font-size: 8.5px; color: var(--faint); text-transform: capitalize; font-weight: 500; }
+.wp-stats { display: flex; flex-direction: column; align-items: flex-end; }
+.wp-stats b { font-family: var(--mono); font-size: 10.5px; }
+.wp-stats small { font-size: 7.5px; color: var(--faint); text-transform: uppercase; letter-spacing: .06em; }
+.wp-lock { position: absolute; right: 7px; top: 5px; font-size: 8px; color: var(--faint); display: flex; align-items: center; gap: 2px; }
+.scope-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; }
+.scope-card { display: flex; flex-direction: column; align-items: flex-start; gap: 2px; padding: 9px; border-radius: 9px; border: 1px solid var(--line); background: rgba(255, 255, 255, .02); color: var(--text); cursor: pointer; text-align: left; transition: .14s; }
+.scope-card:hover { background: rgba(255, 255, 255, .05); }
