576: /* ---------------- releases ---------------- */
577: function chart(key, color, label) {
578:   const data = S.history.length > 1 ? S.history.slice(-90) : [
579:     { week: 1, cash: S.cash, fans: S.fans },
580:     { week: 2, cash: S.cash, fans: S.fans },
581:   ];
582:   const vals = data.map(d => d[key]);
583:   let min = Math.min(...vals);
584:   let max = Math.max(...vals);
585:   if (max - min < 1) { max = min + 1; }
586:   const w = 620, h = 132, pad = 8;
587:   const pts = vals.map((v, i) => [
588:     pad + (i / Math.max(1, vals.length - 1)) * (w - pad * 2),
589:     h - pad - ((v - min) / (max - min)) * (h - pad * 2),
590:   ]);
591:   const line = pts.map((p, i) => `${i ? 'L' : 'M'}${p[0].toFixed(1)} ${p[1].toFixed(1)}`).join(' ');
592:   const area = `${line} L${pts[pts.length - 1][0].toFixed(1)} ${h - pad} L${pts[0][0].toFixed(1)} ${h - pad} Z`;
593:   const last = pts[pts.length - 1];
594:   return `<div class="chart-wrap">
595:     <div class="chart-head"><span>${label}</span><b>${key === 'cash' ? fmtMoney(vals[vals.length - 1]) : fmtNum(vals[vals.length - 1])}</b></div>
596:     <svg viewBox="0 0 ${w} ${h}" class="chart" preserveAspectRatio="none" aria-hidden="true">
597:       <defs><linearGradient id="grad-${key}" x1="0" y1="0" x2="0" y2="1">
598:         <stop offset="0" stop-color="${color}" stop-opacity=".32"/><stop offset="1" stop-color="${color}" stop-opacity="0"/>
599:       </linearGradient></defs>
600:       <path d="${area}" fill="url(#grad-${key})"/>
601:       <path d="${line}" fill="none" stroke="${color}" stroke-width="2.2" stroke-linejoin="round" stroke-linecap="round" vector-effect="non-scaling-stroke"/>
602:       <circle cx="${last[0]}" cy="${last[1]}" r="3.4" fill="${color}"/>
603:     </svg>
604:     <div class="chart-axis"><span>${min === vals[0] ? 'start' : ''}</span><span>last 90 weeks</span></div>
605:   </div>`;
606: }
