127: export function avgMorale() {
128:   if (!S.staff.length) return 0;
129:   return S.staff.reduce((a, m) => a + m.morale, 0) / S.staff.length;
130: }
131: export function avgSkill() {
132:   if (!S.staff.length) return 0;
133:   return S.staff.reduce((a, m) => a + m.skill, 0) / S.staff.length;
