136: /* ---------------- production math ---------------- */
137: export function teamOutput() {
138:   let out = 0;
139:   for (const m of S.staff) out += m.skill * 8.5 * (0.6 + clamp(m.morale, 0, 100) / 100 * 0.5);
140:   if (S.upgrades.includes('desks')) out *= 1.08;
141:   if (S.upgrades.includes('render')) out *= 1.1;
142:   const engine = ENGINES[S.project?.engine || 'basement'];
143:   out *= engine.output;
144:   if (S.project?.crunch) out *= 1.22;
145:   return out;
146: }
147: 
148: export function teamAffinity() {
149:   const sum = { g: 0, a: 0, s: 0, t: 0 };
150:   for (const m of S.staff) {
151:     const aff = ROLES[m.role].affinity;
152:     for (const k of KEYS) sum[k] += aff[k] * m.skill;
153:   }
154:   const total = KEYS.reduce((a, k) => a + sum[k], 0) || 1;
155:   for (const k of KEYS) sum[k] /= total;
156:   return sum;
157: }
158: 
159: export function normalize(obj) {
160:   const total = KEYS.reduce((a, k) => a + Math.max(0, obj[k] || 0), 0);
161:   if (total <= 0) return { g: 0.25, a: 0.25, s: 0.25, t: 0.25 };
162:   const out = {};
163:   for (const k of KEYS) out[k] = Math.max(0, obj[k] || 0) / total;
164:   return out;
165: }
166: 
167: export function focusDist(p) {
168:   return normalize(p ? p.focus : { g: 25, a: 25, s: 25, t: 25 });
169: }
170: 
171: export function achievedDist(p) {
172:   const focus = focusDist(p);
173:   const aff = teamAffinity();
174:   const mix = {};
175:   for (const k of KEYS) mix[k] = focus[k] * 0.6 + aff[k] * 0.4;
176:   return normalize(mix);
177: }
178: 
179: export function distributionFit(p) {
180:   const ideal = GENRES[p.genre].ideal;
181:   const dist = achievedDist(p);
182:   let l1 = 0;
183:   for (const k of KEYS) l1 += Math.abs(dist[k] - ideal[k]);
184:   return clamp(1 - 0.7 * l1, 0.35, 1);
185: }
186: 
187: export function techCeiling(platformId) {
188:   return 3.6 + PLATFORMS[platformId].power * 0.064;
189: }
190: 
191: export function synergyFor(genreId, themeId) {
192:   const g = GENRES[genreId];
193:   if (g.likes.includes(themeId)) return 1.0;
194:   if (g.dislikes.includes(themeId)) return -0.9;
195:   return 0.1;
196: }
197: 
198: export function platformFit(platformId, genreId) {
199:   return AUDIENCE[PLATFORMS[platformId].audience][genreId] ?? 1;
200: }
201: 
202: export function trendBonus(genreId, themeId) {
203:   return (genreId === S.trend.genre ? 0.22 : 0) + (themeId === S.trend.theme ? 0.12 : 0);
204: }
205: 
206: export function upgradeCraft() {
207:   let c = 0;
208:   if (S.upgrades.includes('render')) c += 0.2;
209:   if (S.upgrades.includes('mocap')) c += 0.35;
210:   return c;
211: }
