213: export function projectScore(p, jitter = false) {
214:   const cap = techCeiling(p.platform);
215:   const effort = clamp(p.work / p.required, 0, 1.02);
216:   const fit = distributionFit(p);
217:   const skill = avgSkill();
218:   let score = cap * effort * fit * (1 + (skill - 4) * 0.02);
219:   score += synergyFor(p.genre, p.theme);
220:   score += ENGINES[p.engine].craft + upgradeCraft();
221:   score += trendBonus(p.genre, p.theme);
222:   score += p.polish;
223:   score -= Math.min(3.4, p.bugs * 0.055);
224:   score *= 0.92 + 0.08 * platformFit(p.platform, p.genre);
225:   if (jitter) score += (Math.random() - 0.5) * 0.7;
226:   return clamp(score, 1, 9.9);
227: }
