229: export function forecast(p) {
230:   const projected = p.work >= p.required ? p : { ...p, work: p.required };
231:   const s = projectScore(projected);
232:   return { lo: clamp(s - 0.35, 1, 9.9), hi: clamp(s + 0.35, 1, 9.9), mid: s };
233: }
