235: export function initialHype(marketing) {
236:   return clamp(8 + marketing / 2200 + S.fans / 3000 + S.rep / 6, 5, 100);
237: }
238: 
239: export function progressPct(p) {
240:   return clamp((p.work / p.required) * 100, 0, 100);
241: }
