328: export function shipGame() {
329:   const p = S.project;
330:   if (!p || p.work < p.required) return null;
331:   const score = round1(projectScore(p, true));
332:   const critics = CRITICS.map(c => {
333:     const sc = round1(clamp(score + c.bias + (Math.random() - 0.5) * 0.5, 1, 10));
334:     return { name: c.name, short: c.short, score: sc, quote: quoteFor(sc) };
335:   });
336:   const base = 3500 + S.fans * 0.35 + p.hype * 120;
337:   const reviewMult = 0.3 + Math.pow(score / 10, 2.2) * 2.8;
338:   const hypeMult = 0.75 + p.hype / 100;
339:   const platMult = PLATFORMS[p.platform].share / 26;
340:   const scopeMult = SCOPES[p.scope].sales;
341:   const trendMult = 1 + (p.genre === S.trend.genre ? 0.12 : 0) + (p.theme === S.trend.theme ? 0.08 : 0);
342:   const repMult = 1 + S.rep / 300 + S.fans / 40000;
343:   const aud = platformFit(p.platform, p.genre);
344:   const copies = Math.max(120, Math.round(base * reviewMult * hypeMult * platMult * scopeMult * trendMult * repMult * aud));
345:   const price = SCOPES[p.scope].price;
346:   const gross = Math.round(copies * price);
347:   const cut = Math.round(gross * 0.72);
348:   const schedule = PAYOUT_WEIGHTS.map(w => Math.round(cut * w));
349:   schedule[schedule.length - 1] += cut - schedule.reduce((a, b) => a + b, 0);
350:   const fanGain = Math.max(0, Math.round(copies * Math.max(0, score - 5.5) / 55));
351:   const release = {
352:     id: p.id,
353:     title: p.title,
354:     genre: p.genre,
355:     theme: p.theme,
356:     platform: p.platform,
357:     scope: p.scope,
358:     score,
359:     critics,
360:     copies,
361:     gross,
362:     revenue: cut,
363:     week: S.week,
364:     schedule,
365:     weeksLeft: schedule.length,
366:     paid: 0,
367:     fans: fanGain,
368:     hype: Math.round(p.hype),
369:     goty: false,
370:     marketing: p.marketing,
371:   };
372:   S.releases.unshift(release);
373:   S.fans += fanGain;
374:   S.rep = clamp(S.rep + (score - 5.5) * 1.35, 0, 100);
375:   S.totals.copies += copies;
376:   S.totals.revenue += cut;
377:   if (S.history.length) {
378:     Object.assign(S.history[S.history.length - 1], { cash: Math.round(S.cash), fans: Math.round(S.fans), rep: Math.round(S.rep) });
379:   }
380:   S.project = null;
381:   addNews(score >= 8 ? 'good' : score >= 6 ? 'info' : 'bad',
382:     `${release.title} shipped to ${score.toFixed(1)}/10 reviews and ${copies.toLocaleString()} sales.`);
383:   const unlocked = checkAchievements();
384:   return { release, unlocked };
385: }
