515: /* ---------------- week tick ---------------- */
516: export function advanceWeek() {
517:   if (!S || S.gameOver) return { toasts: [], award: null, bankrupt: false };
518:   const toasts = [];
519:   const p = S.project;
520: 
521:   if (p) {
522:     const out = teamOutput();
523:     const dist = achievedDist(p);
524:     p.work += out;
525:     for (const k of KEYS) p.points[k] += out * dist[k];
526:     p.weeks += 1;
527:     const morale = avgMorale();
528:     p.bugs += 0.45 + SCOPES[p.scope].bugs + (morale < 50 ? 0.5 : 0) + (p.crunch ? 0.35 : 0) + Math.random() * 0.35;
529:     if (p.work >= p.required) {
530:       if (!p.polishStarted) {
531:         p.polishStarted = true;
532:         toasts.push({ kind: 'good', text: `${p.title} is feature-complete. Polish it or ship it.` });
533:         addNews('production', `${p.title} reached feature-complete. The polish phase begins.`);
534:       }
535:       p.bugs = Math.max(0, p.bugs - (2.5 + S.staff.length * 0.9));
536:       p.polish = Math.min(0.8, p.polish + 0.1);
537:       p.polishWeeks += 1;
538:     }
539:   }
540: 
541:   // royalties from shipped games
542:   let royalties = 0;
543:   for (const r of S.releases) {
544:     if (r.weeksLeft > 0) {
545:       const idx = r.schedule.length - r.weeksLeft;
546:       const amt = r.schedule[idx] || 0;
547:       S.cash += amt;
548:       S.totals.revenue += amt;
549:       r.paid += amt;
550:       r.weeksLeft -= 1;
551:       royalties += amt;
552:     }
553:   }
554: 
555:   // payroll
556:   const pay = payroll();
557:   S.cash -= pay;
558:   S.totals.spent += pay;
559: 
560:   // research
561:   const rpGain = 2 + S.staff.length * 0.6 + S.staff.reduce((a, m) => a + m.skill, 0) * 0.12;
562:   S.rp = Math.min(999, S.rp + rpGain);
563: 
564:   // morale
565:   for (const m of S.staff) {
566:     let decay = 2.4;
567:     if (S.upgrades.includes('coffee')) decay *= 0.5;
568:     if (S.upgrades.includes('arcade')) decay -= 1.4;
569:     if (p?.crunch) decay += 2.2;
570:     m.morale = clamp(m.morale - decay, 5, 100);
571:   }
572: 
573:   // candidates rotate
574:   refreshCandidates(false);
575: 
576:   // market pulse
577:   if (S.week - S.trendWeek >= 7) {
578:     S.trend = rollTrend();
579:     S.trendWeek = S.week;
580:     addNews('market', `Market pulse: ${GENRES[S.trend.genre].name} + ${THEMES[S.trend.theme].name} is trending.`);
581:   }
582: 
583:   // random event
584:   if (Math.random() < 0.22) {
585:     let ev = pick(EVENT_POOL);
586:     if (ev.id === S.lastEvent) ev = pick(EVENT_POOL);
587:     S.lastEvent = ev.id;
588:     ev.apply(S);
589:     addNews(ev.kind, ev.text);
590:     toasts.push({ kind: ev.kind, text: ev.text });
591:   }
592: 
593:   // advance the clock
594:   S.week += 1;
595:   S.history.push({ week: S.week, cash: Math.round(S.cash), fans: Math.round(S.fans), rep: Math.round(S.rep) });
596:   if (S.history.length > 300) S.history.shift();
597: 
598:   // end-of-year awards
599:   let award = null;
600:   if (S.week > 1 && (S.week - 1) % 52 === 0) {
601:     const recent = S.releases.filter(r => r.week >= S.week - 52);
602:     if (recent.length) {
603:       const best = recent.reduce((a, b) => (a.score > b.score ? a : b));
604:       const rival = 7.7 + Math.random() * 1.7;
605:       if (best.score >= rival) {
606:         best.goty = true;
607:         S.awards += 1;
608:         S.fans += 3000 + Math.round(best.copies * 0.05);
609:         S.cash += 75000;
610:         addNews('award', `${best.title} wins Game of the Year! The trophy shelf begins.`);
611:         award = { won: true, title: best.title, score: best.score, rival: round1(rival) };
612:       } else {
613:         addNews('industry', `${best.title} was nominated for GOTY but lost to a rival (${rival.toFixed(1)}).`);
614:         award = { won: false, title: best.title, score: best.score, rival: round1(rival) };
615:       }
616:     } else {
617:       addNews('industry', 'The annual awards show crowns another studio. You were not nominated.');
618:       award = { won: false, none: true };
619:     }
620:   }
621: 
622:   // achievements + solvency
623:   const unlocked = checkAchievements();
624:   for (const a of unlocked) toasts.push({ kind: 'good', text: `Achievement: ${a.name}` });
625: 
626:   let bankrupt = false;
627:   if (S.cash < 0) {
628:     S.negativeWeeks += 1;
629:     if (S.negativeWeeks >= 2) {
630:       S.gameOver = true;
631:       bankrupt = true;
632:       addNews('bad', 'The studio ran out of money. The lights are off.');
633:     } else {
634:       toasts.push({ kind: 'bad', text: 'Payroll pushed you into the red. Fix this next week or fold.' });
635:     }
636:   } else {
637:     S.negativeWeeks = 0;
638:   }
639: 
640:   return { toasts, award, bankrupt, royalties, pay };
641: }

:root {
  --bg: #070a0f;
  --bg2: #0b1017;
  --panel: #101722;
  --panel2: #151e2b;
  --line: #212d3c;
  --line2: #2d3d51;
  --text: #e9eff8;
  --muted: #8d9bb0;
  --faint: #5d6b7f;
  --teal: #5eead4;
  --violet: #a78bfa;
  --amber: #fbbf24;
  --pink: #f472b6;
  --red: #fb7185;
  --green: #a3e635;
  --mono: ui-monospace, "SF Mono", "Cascadia Code", Menlo, Consolas, monospace;
  --sans: "Inter", "Segoe UI", system-ui, -apple-system, Roboto, sans-serif;
  --radius: 16px;
  --shadow: 0 30px 70px -35px rgba(0, 0, 0, .95);
}

* { box-sizing: border-box; }
[hidden] { display: none !important; }
html, body { height: 100%; }
body {
  margin: 0;
  font-family: var(--sans);
  color: var(--text);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
  overflow: hidden;
}
body::before {
  content: "";
  position: fixed;
  inset: 0;
  background:
    radial-gradient(900px 600px at 12% -10%, rgba(94, 234, 212, .07), transparent 60%),
    radial-gradient(800px 500px at 95% 0%, rgba(167, 139, 250, .07), transparent 55%),
    radial-gradient(700px 700px at 50% 120%, rgba(56, 189, 248, .04), transparent 60%),
    var(--bg);
  z-index: -2;
  pointer-events: none;
}
body::after {
  content: "";
  position: fixed;
  inset: 0;
  background-image: linear-gradient(rgba(255, 255, 255, .018) 1px, transparent 1px), linear-gradient(90deg, rgba(255, 255, 255, .018) 1px, transparent 1px);
  background-size: 44px 44px;
  mask-image: radial-gradient(ellipse at 50% 0%, #000 10%, transparent 75%);
  z-index: -1;
  pointer-events: none;
}

h1, h2, h3, h4, p { margin: 0; }
h1 { font-size: 30px; letter-spacing: -.035em; font-weight: 750; }
h2 { font-size: 18px; letter-spacing: -.02em; font-weight: 700; }
h3 { font-size: 15px; letter-spacing: -.01em; font-weight: 700; }
b { font-weight: 700; }
small { font-size: 11.5px; }
button { font-family: inherit; }
input { font-family: inherit; }
::selection { background: rgba(94, 234, 212, .28); }

::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: #253243; border-radius: 99px; border: 2px solid var(--bg); }
::-webkit-scrollbar-thumb:hover { background: #34465c; }

:focus-visible { outline: 2px solid rgba(94, 234, 212, .8); outline-offset: 2px; }

.ic { flex: none; vertical-align: -3px; }
.muted { color: var(--muted); font-weight: 500; }
.sub { color: var(--muted); font-size: 13.5px; line-height: 1.55; }
.eyebrow { font-family: var(--mono); font-size: 10px; letter-spacing: .19em; color: var(--faint); text-transform: uppercase; }
.pos { color: var(--teal); }
.neg { color: var(--red); }
.danger-text { color: var(--red) !important; }
